[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
# 守る: Docs/Guides/Working/scape-tool-basic-design.md
# 守る: Docs/Guides/Working/scape-m1-detailed-design.md
# 守る: Docs/Guides/Procedures/issue-goal-setting.md
# 守る: .claude/skills/design-cycle/SKILL.md
# （書かせる設計書は変数で指す）
$dir = 'Docs/Guides/Working'; $d = "$dir/scape-s4b-detailed-design.md"
if (-not (Test-Path $d)) { Write-Host "まだ無い: $d"; exit 1 }
$t = Get-Content $d -Raw -Encoding utf8
# コードブロックの中の行頭の # は見出しとして数えない（開いた記号の長さで閉じを見る）
$fence = ''
$s = (($t -split "`n") | ForEach-Object {
        if ($fence) { if ($_ -match ('^' + $fence + '`*\s*$')) { $fence = ''; $_ } else { $_ -replace '^#', ' ' } }
        elseif ($_ -match '^(`{3,})') { $fence = $Matches[1]; $_ }
        else { $_ }
    }) -join "`n"
if ($t.Length -lt 15000) { Write-Host "全体が短い: $($t.Length) 字（15,000 字以上）"; exit 1 }
$h1 = ([regex]::Matches($s, '(?m)^# ')).Count
if ($h1 -ne 1) { Write-Host "見出し 1 が $h1 個（1 個にする）"; exit 1 }
if (-not [regex]::IsMatch($s, '(?m)^## 0\.')) { Write-Host '## 0. の節が無い'; exit 1 }
foreach ($w in '事実の確認', '操作', 'カメラ', '自キャラ', '撮影の一人称', '微調整', '保存の知らせ', '日本語', '既存のテスト', 'テストの一覧', 'Issue の分け方') {
    if (-not [regex]::IsMatch($s, "(?m)^##+ .*$([regex]::Escape($w))")) { Write-Host "節が無い（見出しに「$w」）"; exit 1 }
}
foreach ($w in '画像を保存しました', '保存できませんでした') { if (-not $t.Contains($w)) { Write-Host "知らせの文「$w」が無い"; exit 1 } }
# M1 のテスト 54 本（M1 詳細設計 9 章の表）を、全部「既存のテストの扱い」で挙げているか
$m1doc = Get-Content "$dir/scape-m1-detailed-design.md" -Raw -Encoding utf8
$m1 = @([regex]::Matches($m1doc, '(?m)^\| `(KaedeScapeBuii\.Tests\.(?:EditMode|PlayMode)\.\w+\.\w+)` \| (?:S1|S2|S4|S6a|S6b) \|') | ForEach-Object { $_.Groups[1].Value })
if ($m1.Count -ne 54) { Write-Host "M1 詳細設計のテストの行が $($m1.Count) 本（54 本のはず）"; exit 1 }
$miss = @($m1 | Where-Object { -not $t.Contains($_) })
if ($miss.Count) { Write-Host "既存のテストの扱いに無い M1 のテスト $($miss.Count) 本（例: $($miss[0])）"; exit 1 }
# 新しいテストの名前（M1 に無いもの）が 10 個以上・PlayMode を含む
$all = @([regex]::Matches($t, 'KaedeScapeBuii\.Tests\.(?:EditMode|PlayMode)\.\w+\.\w+') | ForEach-Object { $_.Value } | Select-Object -Unique)
$new = @($all | Where-Object { $m1 -notcontains $_ })
if ($new.Count -lt 10) { Write-Host "新しいテストの名前が $($new.Count) 個（10 個以上）"; exit 1 }
if (-not ($new -match '\.PlayMode\.')) { Write-Host '新しいテストに PlayMode が無い'; exit 1 }
# 「Issue の分け方」の節（次の ## まで）の中の ```pwsh
$m = [regex]::Match($s, '(?ms)^##+ [^\n]*Issue の分け方.*?(?=^## |\z)')
$pw = ([regex]::Matches($m.Value, '(?m)^\s*```pwsh')).Count
if ($pw -lt 1) { Write-Host 'Issue の分け方の節に確認コマンドの案（```pwsh）が無い'; exit 1 }
if (([regex]::Matches($t, '(?m)^```mermaid')).Count -lt 1) { Write-Host 'Mermaid の図が無い'; exit 1 }
if (git status --porcelain -- Assets Scripts Packages ProjectSettings) { Write-Host 'コード・設定を変えている（文書だけの Issue）'; exit 1 }
Write-Host 'OK'
exit 0
